UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "f''c = 21 MPa (3000 psi) - minimum", "type": "fact"}, {"text": "f''c = 24 MPa", "type": "fact"}, {"text": "f''c = 28 MPa (4000 psi) - standard", "type": "fact"}, {"text": "f''c = 30 MPa", "type": "fact"}, {"text": "f''c = 35 MPa (5000 psi) - high-strength", "type": "fact"}, {"text": "Strength Determination: Based on 28-day compressive strength of 150mm diameter cylinders", "type": "fact"}, {"text": "Name: Allowable Stress Design (older method)", "type": "concept"}, {"text": "Application: For comparison and certain applications", "type": "fact"}, {"text": "Principle: Actual stress ≤ Allowable stress (f''c/safety factor)", "type": "concept"}, {"text": "Name: Load and Resistance Factor Design (current - NSCP 2015)", "type": "fact"}, {"text": "Principle: Strength Design - Ultimate capacity must exceed factored loads", "type": "concept"}, {"text": "Combined 1 2D Plus 1 6L: Most common", "type": "fact"}, {"text": "Wind Or Seismic: 0.9D + 1.3W or 0.9D + E", "type": "fact"}, {"text": "Modulus Of Elasticity: Ec = 4700√(f''c) MPa", "type": "fact"}, {"text": "Poisson Ratio: 0.15-0.20", "type": "fact"}, {"text": "Thermal Expansion: α = 10-14 × 10⁻⁶/°C", "type": "fact"}, {"text": "Density: 2400 kg/m³ (normal weight)", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-STRC-002-01';
