UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Description: Longitudinal bars held by lateral ties (hoops)", "type": "fact"}, {"text": "Longitudinal Bars: Minimum 4 bars for rectangular, 6 for round", "type": "fact"}, {"text": "Diameter: 1/4 of longitudinal bar diameter, min 9.5mm", "type": "fact"}, {"text": "Spacing: 16 × longitudinal bar diameter or 48 × tie diameter", "type": "fact"}, {"text": "Application: General use - lower ductility", "type": "fact"}, {"text": "Description: Longitudinal bars enclosed by continuous helical spiral", "type": "fact"}, {"text": "Spiral Requirements: Pitch and diameter per ACI 318 Section 10.9.6", "type": "fact"}, {"text": "Application: Higher ductility, suitable for seismic areas", "type": "fact"}, {"text": "Strength Increase: 5-10% higher capacity than tied columns", "type": "fact"}, {"text": "Pure Compression: Ideal case - rarely occurs", "type": "fact"}, {"text": "Biaxial Bending: Combined bending in two directions", "type": "fact"}, {"text": "Interaction Diagram: Used for axial load + moment combinations", "type": "fact"}, {"text": "Description: Supported on two parallel sides, reinforcement in one direction", "type": "fact"}, {"text": "Analysis: As continuous beam spanning short direction", "type": "fact"}, {"text": "Application: Rectangular areas with aspect ratio > 2", "type": "fact"}, {"text": "Description: Supported on all four sides, reinforcement in both directions", "type": "fact"}, {"text": "Yield line method", "type": "concept"}, {"text": "Coefficient method (NSCP Table 408.6.5.2)", "type": "concept"}, {"text": "Finite element analysis", "type": "fact"}, {"text": "Application: Square or near-square areas, Aspect ratio < 2", "type": "fact"}, {"text": "Description: Joists with solid ribs and recessed areas", "type": "fact"}, {"text": "Advantages: Reduced weight, improved span capability", "type": "fact"}, {"text": "Application: Large spans with moderate loads", "type": "fact"}, {"text": "Description: Slab connected directly to columns without beams or drops", "type": "fact"}, {"text": "Shear Requirements: Higher shear stress at columns - punching shear critical", "type": "fact"}, {"text": "Application: Flexible open floor plans", "type": "fact"}, {"text": "Description: Flat plate with column capitals and/or drop panels", "type": "fact"}, {"text": "Advantages: Reduced negative moment at columns", "type": "fact"}, {"text": "Failure Mode: Slab-column junction failure under vertical load", "type": "fact"}, {"text": "Critical Perimeter: b₀ = perimeter at d/2 from column face", "type": "fact"}, {"text": "Formula: vc = Vu/(b₀·d)", "type": "fact"}, {"text": "Strength Limit: vc ≤ 0.33√(f''c) for interior columns", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-STRC-002-04';
UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Description: Individual pads supporting single columns", "type": "fact"}, {"text": "Shape: Square or rectangular", "type": "fact"}, {"text": "Application: Light to medium loads, good bearing soil", "type": "fact"}, {"text": "Bearing capacity (geotechnical)", "type": "fact"}, {"text": "Flexural capacity", "type": "fact"}, {"text": "Punching shear", "type": "fact"}, {"text": "Bending moment at critical section", "type": "fact"}, {"text": "Description: Single footing supporting two or more columns", "type": "fact"}, {"text": "Application: Space constraints, unequal loads", "type": "fact"}, {"text": "Analysis: Static equilibrium + moment balance", "type": "fact"}, {"text": "Description: Continuous slab covering entire building footprint", "type": "fact"}, {"text": "Application: Poor bearing soil, heavy structures, large settlements expected", "type": "fact"}, {"text": "Advantages: Distributes loads over large area", "type": "fact"}, {"text": "Driven piles (displacement piles)", "type": "fact"}, {"text": "Bored piles/drilled shafts (non-displacement)", "type": "fact"}, {"text": "Screw piles", "type": "fact"}, {"text": "Composite piles", "type": "fact"}, {"text": "End bearing (tip resistance)", "type": "fact"}, {"text": "Skin friction (shaft resistance)", "type": "fact"}, {"text": "Total capacity = End bearing + Skin friction", "type": "fact"}, {"text": "Application: Very poor surface soil, heavy loads, deep bearing strata", "type": "fact"}, {"text": "Load Transfer: Through skin friction and end bearing to stable layers", "type": "fact"}, {"text": "Description: Large diameter deep foundation cylinders", "type": "fact"}, {"text": "Construction: Open or pneumatic caissons", "type": "fact"}, {"text": "Application: Very large loads, bridge foundations", "type": "fact"}, {"text": "Soil Bearing Capacity: Determined by geotechnical investigation", "type": "fact"}, {"text": "Allowable Bearing Pressure: Typically 100-300 kPa