UPDATE public.taxonomy_tree SET wiki_items = '[{"text": "Definition: Steel beam with reinforced concrete slab acting together through shear studs", "type": "definition"}, {"text": "Increased strength and stiffness", "type": "fact"}, {"text": "Reduced steel section (more economical)", "type": "fact"}, {"text": "Improved fire resistance (concrete provides insulation)", "type": "fact"}, {"text": "Better vibration control", "type": "fact"}, {"text": "Description: Headed studs welded to top of steel beam", "type": "fact"}, {"text": "Purpose: Prevent slip between steel and concrete", "type": "fact"}, {"text": "Spacing: Typically 200-300mm on center", "type": "fact"}, {"text": "Diameter: Usually 16-20mm", "type": "fact"}, {"text": "Force Transfer: Shear studs transmit horizontal shear forces", "type": "fact"}, {"text": "No Slip Assumption: Steel and concrete move together as one unit", "type": "fact"}, {"text": "Design Method: AISC/NSCP procedures", "type": "concept"}, {"text": "Composite section analysis (transformed section)", "type": "fact"}, {"text": "Flexural capacity of composite section", "type": "fact"}, {"text": "Stud shear capacity (number of studs needed)", "type": "fact"}, {"text": "Concrete slab strength and reinforcement", "type": "fact"}, {"text": "Deflection of composite member", "type": "fact"}, {"text": "Calculation: Composite I includes steel + concrete contributions", "type": "fact"}, {"text": "Transformation: Concrete area divided by n = Esteel/Econcrete", "type": "fact"}, {"text": "Effect: Much larger than steel beam alone", "type": "fact"}]'::jsonb, updated_at = now() WHERE ale_id = 'ALE-STRC-005-01';
